SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(3*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");root:="work/deg10/continuation_20261031b/C56/";a:=eval Read(root cat "inputs/fourmap_filter.m");k:=GF(3);R:=PolynomialRing(k);fs:=AssociativeArray();for v in a[1]do fs[v[1]]:=ext<k|R!v[2]>;end for;active:={};for row in a[4]do for si in row[2]do Include(~active,si);end for;end for;
function Ky(v,d)vs:=[];for j in[1..d]do Append(~vs,&cat[[Integers()!a:a in Eltseq(z,k)]:z in v]);v:=[z^3:z in v];end for;return Sort(vs)[1];end function;
records:=[* *];for si in Sort(Setseq(active))do r:=a[2][si];d:=r[2];ky:=r[3];K:=fs[d];b:=Evaluate(R!ky[1..d],K.1);c:=Evaluate(R!ky[d+1..2*d],K.1);E:=EllipticCurve([K|1-c,-b,-b,0,0]);P:=E![0,0];assert Order(P)eq 56;RK<X>:=PolynomialRing(K);T:=28*P;EE,iso:=IsogenyFromKernel(E,X-T[1]);Q:=iso(P);dual:=DualIsogeny(iso);assert Order(Q)eq 28 and dual(Q)eq 2*P;ai:=aInvariants(EE);ts:=[EE![v[1],-(ai[1]*v[1]+ai[3])/2]:v in Roots(DivisionPolynomial(EE,2))];ds:=[S:S in ts|dual(S)eq E!0];assert #ds eq 1;P2:=ds[1];assert P2 ne 14*Q;bc:=DerickxNormalForm_bc(EE,P2,Q);e:=LCM([Degree(MinimalPolynomial(z,k)):z in bc]);assert d mod e eq 0;Append(~records,[*si,d,Ky(bc,d),e,d div e*]);end for;
cases:=[[*z[1],z[2],z[3]*]:z in a[4]];Write(root cat "projected_Y28.m",Sprint([*a[1],records,cases*]):Overwrite:=true);print "D31B_C56_PROJECT_Y28_COMPLETE",#records,#cases,Cputime(tt);quit;
